#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

struct NLLLossTilingData {
    int64_t totalLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t numClasses;
    int64_t innerSize;
    int64_t hasWeight;
    int64_t ignoreIndex;
    int64_t reductionMode;
    int64_t outputNumElements;
};

template<typename T>
class NLLLossKernel {
public:
    __aicore__ inline NLLLossKernel() {}
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR target, GM_ADDR weight,
                                 GM_ADDR output, GM_ADDR workspaceSum, GM_ADDR workspaceCount,
                                 NLLLossTilingData tilingData);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength);
    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength,
                                     float &partialSum, int64_t &validCount);
    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength);

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> targetQueue;
    TQue<TPosition::VECIN, 1> inputValQueue;
    TBuf<TPosition::VECCALC> computeBuf;
    TBuf<TPosition::VECCALC> castInputBuf;
    TQue<TPosition::VECOUT, BUFFER_NUM> outputQueue;
    TBuf<TPosition::VECCALC> weightBuf;

    GlobalTensor<T> inputGm;
    GlobalTensor<int32_t> targetGm;
    GlobalTensor<T> weightGm;
    GlobalTensor<T> outputGm;
    GlobalTensor<float> workspaceSumGm;
    GlobalTensor<int64_t> workspaceCountGm;

    NLLLossTilingData tilingData_;
    int64_t coreOffset_;
    int64_t coreLength_;
};

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Init(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR workspaceSum, GM_ADDR workspaceCount,
    NLLLossTilingData tilingData) {

    tilingData_ = tilingData;
    int64_t tileLength = tilingData_.tileLength;

    // Compute core offset and length
    int64_t blockIdx = GetBlockIdx();
    if (blockIdx < tilingData_.formerNum) {
        coreOffset_ = blockIdx * tilingData_.formerLength;
        coreLength_ = tilingData_.formerLength;
    } else {
        int64_t tailIdx = blockIdx - tilingData_.formerNum;
        coreOffset_ = tilingData_.formerNum * tilingData_.formerLength
                    + tailIdx * tilingData_.tailLength;
        coreLength_ = tilingData_.tailLength;
    }

    int64_t totalInputElems = tilingData_.numClasses * tilingData_.innerSize
                            * (tilingData_.totalLength / tilingData_.innerSize);
    inputGm.SetGlobalBuffer((__gm__ T*)input, totalInputElems);
    targetGm.SetGlobalBuffer((__gm__ int32_t*)target, tilingData_.totalLength);
    if (tilingData_.hasWeight) {
        weightGm.SetGlobalBuffer((__gm__ T*)weight, tilingData_.numClasses);
        pipe.InitBuffer(weightBuf, tilingData_.numClasses * sizeof(T));
    }
    outputGm.SetGlobalBuffer((__gm__ T*)output, tilingData_.outputNumElements);
    if (tilingData_.reductionMode == 1 || tilingData_.reductionMode == 2) {
        workspaceSumGm.SetGlobalBuffer((__gm__ float*)workspaceSum);
        workspaceCountGm.SetGlobalBuffer((__gm__ int64_t*)workspaceCount);
    }

    // Init buffers
    pipe.InitBuffer(targetQueue, BUFFER_NUM, tileLength * sizeof(int32_t));
    pipe.InitBuffer(inputValQueue, 1, 8);  // single element, 8 bytes aligned for fp64 safety
    pipe.InitBuffer(computeBuf, tileLength * sizeof(float));
    pipe.InitBuffer(castInputBuf, tileLength * sizeof(float));
    if (tilingData_.reductionMode == 0) {
        pipe.InitBuffer(outputQueue, BUFFER_NUM, tileLength * sizeof(T));
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Process() {
    if (coreLength_ <= 0) return;

    int64_t tileNum = (coreLength_ + tilingData_.tileLength - 1) / tilingData_.tileLength;

    float partialSum = 0.0f;
    int64_t validCount = 0;

    // Load weight into UB once if present
    if (tilingData_.hasWeight) {
        LocalTensor<T> weightLocal = weightBuf.Get<T>();
        DataCopyExtParams weightCopyParams;
        weightCopyParams.blockCount = 1;
        weightCopyParams.blockLen = static_cast<uint32_t>(tilingData_.numClasses * sizeof(T));
        weightCopyParams.srcStride = 0;
        weightCopyParams.dstStride = 0;
        DataCopyPadExtParams<T> weightPadParams;
        weightPadParams.isPad = false;
        DataCopyPad(weightLocal, weightGm, weightCopyParams, weightPadParams);
        PipeBarrier<PIPE_ALL>();
    }

    for (int64_t i = 0; i < tileNum - 1; ++i) {
        CopyIn(i, tilingData_.tileLength);
        Compute(i, tilingData_.tileLength, partialSum, validCount);
        if (tilingData_.reductionMode == 0) {
            CopyOut(i, tilingData_.tileLength);
        }
    }

    // Tail tile
    int64_t tailTileLength = coreLength_ - (tileNum - 1) * tilingData_.tileLength;
    if (tailTileLength > 0) {
        CopyIn(tileNum - 1, tailTileLength);
        Compute(tileNum - 1, tailTileLength, partialSum, validCount);
        if (tilingData_.reductionMode == 0) {
            CopyOut(tileNum - 1, tailTileLength);
        }
    }

    // Write partial results for mean/sum
    if (tilingData_.reductionMode == 1 || tilingData_.reductionMode == 2) {
        int64_t blockIdx = GetBlockIdx();
        LocalTensor<float> sumTensor = computeBuf.Get<float>();
        sumTensor.SetValue(0, partialSum);
        workspaceSumGm.SetValue(blockIdx, partialSum);
        workspaceCountGm.SetValue(blockIdx, validCount);
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CopyIn(int64_t progress, int64_t curTileLength) {
    LocalTensor<int32_t> targetLocal = targetQueue.AllocTensor<int32_t>();
    int64_t elemStart = coreOffset_ + progress * tilingData_.tileLength;
    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(int32_t));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;
    DataCopyPadExtParams<int32_t> padParams;
    padParams.isPad = false;
    DataCopyPad(targetLocal, targetGm[elemStart], copyParams, padParams);
    targetQueue.EnQue(targetLocal);
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Compute(
    int64_t progress, int64_t curTileLength,
    float &partialSum, int64_t &validCount) {

    LocalTensor<int32_t> targetLocal = targetQueue.DeQue<int32_t>();
    LocalTensor<float> computeLocal = computeBuf.Get<float>();

    if constexpr (sizeof(T) == sizeof(float)) {
        // FP32 path
        for (int64_t elem = 0; elem < curTileLength; ++elem) {
            int32_t classIdx = targetLocal.GetValue(elem);
            if (classIdx == tilingData_.ignoreIndex) {
                if (tilingData_.reductionMode == 0) {
                    computeLocal.SetValue(elem, 0.0f);
                }
                continue;
            }

            int64_t globalElemIdx = coreOffset_ + progress * tilingData_.tileLength + elem;
            int64_t n = globalElemIdx / tilingData_.innerSize;
            int64_t rowIdx = globalElemIdx % tilingData_.innerSize;
            int64_t inputOffset = n * tilingData_.numClasses * tilingData_.innerSize
                                + static_cast<int64_t>(classIdx) * tilingData_.innerSize
                                + rowIdx;

            float val = static_cast<float>(inputGm.GetValue(inputOffset));
            val = -val;

            if (tilingData_.hasWeight) {
                LocalTensor<T> weightLocal = weightBuf.Get<T>();
                float w = static_cast<float>(weightLocal.GetValue(classIdx));
                val *= w;
            }

            if (tilingData_.reductionMode == 0) {
                computeLocal.SetValue(elem, val);
            } else {
                partialSum += val;
            }
            validCount++;
        }
    } else {
        // FP16/BF16 path: cast computations
        LocalTensor<float> castInputLocal = castInputBuf.Get<float>();
        LocalTensor<T> inputValLocal = inputValQueue.AllocTensor<T>();

        for (int64_t elem = 0; elem < curTileLength; ++elem) {
            int32_t classIdx = targetLocal.GetValue(elem);
            if (classIdx == tilingData_.ignoreIndex) {
                if (tilingData_.reductionMode == 0) {
                    computeLocal.SetValue(elem, 0.0f);
                }
                continue;
            }

            int64_t globalElemIdx = coreOffset_ + progress * tilingData_.tileLength + elem;
            int64_t n = globalElemIdx / tilingData_.innerSize;
            int64_t rowIdx = globalElemIdx % tilingData_.innerSize;
            int64_t inputOffset = n * tilingData_.numClasses * tilingData_.innerSize
                                + static_cast<int64_t>(classIdx) * tilingData_.innerSize
                                + rowIdx;

            // Load single input element
            T inputVal = inputGm.GetValue(inputOffset);
            inputValLocal.SetValue(0, inputVal);
            Cast(castInputLocal, inputValLocal, CAST_NONE, 1);
            float val = castInputLocal.GetValue(0);
            val = -val;

            if (tilingData_.hasWeight) {
                LocalTensor<T> weightLocal = weightBuf.Get<T>();
                T wVal = weightLocal.GetValue(classIdx);
                inputValLocal.SetValue(0, wVal);
                Cast(castInputLocal, inputValLocal, CAST_NONE, 1);
                val *= castInputLocal.GetValue(0);
            }

            if (tilingData_.reductionMode == 0) {
                computeLocal.SetValue(elem, val);
            } else {
                partialSum += val;
            }
            validCount++;
        }
    }

    targetQueue.FreeTensor(targetLocal);

    if (tilingData_.reductionMode == 0) {
        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: copy computeLocal to output (already FP32)
            LocalTensor<T> outputLocal = outputQueue.AllocTensor<T>();
            LocalTensor<float> compLocal = computeBuf.Get<float>();
            for (int64_t elem = 0; elem < curTileLength; ++elem) {
                outputLocal.SetValue(elem, static_cast<T>(compLocal.GetValue(elem)));
            }
            outputQueue.EnQue(outputLocal);
        } else {
            // FP16/BF16: Cast computeLocal (FP32) to outputLocal (FP16/BF16)
            LocalTensor<T> outputLocal = outputQueue.AllocTensor<T>();
            Cast(outputLocal, computeLocal, CAST_ROUND, curTileLength);
            outputQueue.EnQue(outputLocal);
        }
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CopyOut(int64_t progress, int64_t curTileLength) {
    LocalTensor<T> outputLocal = outputQueue.DeQue<T>();
    int64_t outputStart = coreOffset_ + progress * tilingData_.tileLength;
    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;
    DataCopyPad(outputGm[outputStart], outputLocal, copyParams);
    outputQueue.FreeTensor(outputLocal);
}

