    // ---- Tiling Data ----
    NLLLossTilingData tiling;
    tiling.totalLength = totalLength;
    tiling.formerNum = formerNumVal;
    tiling.formerLength = formerLengthVal;
    tiling.tailNum = tailNumVal;
    tiling.tailLength = tailLengthVal;
    tiling.tileLength = tileLength;
    tiling.numClasses = C;
    tiling.innerSize = innerSize;
    tiling.hasWeight = hasWeight;
    tiling.ignoreIndex = ignore_index;
    tiling.reductionMode = reductionMode;
    tiling.outputNumElements = outputNumElements;
    tiling.dtypeSize = dtypeSizeVal;

