    // All parameters to EXEC_KERNEL_CMD must be lvalues
    uint32_t blockDim_ = static_cast<uint32_t>(usedCoreNum);
    if (blockDim_ < 1) blockDim_ = 1;

    // Need weight pointer even if no weight (pass a valid dummy tensor)
    if (!hasWeight) {
        weightContiguous = at::empty({1},
            inputContiguous.options().dtype(inputContiguous.scalar_type()));
    }

    // These are the lvalues for EXEC_KERNEL_CMD
    // All must be named variables (lvalues), not temporaries
    at::Tensor inputArg = inputContiguous;
    at::Tensor targetArg = targetInt32;
    at::Tensor weightArg = weightContiguous;
    at::Tensor outputArg = output;
    at::Tensor wsSumArg = workspaceSum;
    at::Tensor wsCountArg = workspaceCount;
    NLLLossTilingData tilingArg = tiling;

    EXEC_KERNEL_CMD(nll_loss, blockDim_,
                    inputArg, targetArg, weightArg,
                    outputArg, wsSumArg, wsCountArg,
                    tilingArg);

    // ---- Post-processing for mean/sum ----
    if (reductionMode == 1 || reductionMode == 2) {
        // Read workspace from device to CPU
        at::Tensor sumCpu = workspaceSum.to(at::kCPU);
        at::Tensor countCpu = workspaceCount.to(at::kCPU);

        float totalSum = 0.0f;
        int64_t totalCount = 0;
        auto sumAcc = sumCpu.accessor<float, 1>();
        auto countAcc = countCpu.accessor<int64_t, 1>();

        for (int64_t i = 0; i < coreNum; ++i) {
            totalSum += sumAcc[i];
            totalCount += countAcc[i];
        }

        if (reductionMode == 1) {
            // "mean": divide by valid count
            if (totalCount > 0) {
                totalSum /= static_cast<float>(totalCount);
            }
        }

        // Write scalar result to output tensor (on NPU device)
        // Create CPU scalar and copy to device
        at::Tensor cpuScalar;
        if (inputContiguous.scalar_type() == at::kFloat) {
            cpuScalar = at::scalar_tensor(static_cast<double>(totalSum),
                at::TensorOptions().dtype(at::kFloat).device(at::kCPU));
        } else if (inputContiguous.scalar_type() == at::kHalf) {
            cpuScalar = at::scalar_tensor(static_cast<double>(totalSum),
                at::TensorOptions().dtype(at::kHalf).device(at::kCPU));
        } else {
            // bfloat16
            cpuScalar = at::scalar_tensor(static_cast<double>(totalSum),
                at::TensorOptions().dtype(at::kBFloat16).device(at::kCPU));
        }
        output.copy_(cpuScalar);
    }

    return output;
}

}  // namespace ascend_kernel
