#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "nll_loss_tiling.h"
#include "aclrtlaunch_nll_loss.h"
#include <torch/extension.h>

namespace ascend_kernel {

namespace {
constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
}  // namespace

at::Tensor nll_loss(
    const at::Tensor &input,
    const at::Tensor &target,
    const c10::optional<at::Tensor> &weight_opt,
    int64_t ignore_index,
    c10::string_view reduction) {

    // ---- 输入校验 ----
    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
                "nll_loss: input must be on NPU device");
    TORCH_CHECK(target.device().type() == at::DeviceType::PrivateUse1,
                "nll_loss: target must be on NPU device");
    TORCH_CHECK(input.scalar_type() == at::kFloat ||
                input.scalar_type() == at::kHalf ||
                input.scalar_type() == at::kBFloat16,
                "nll_loss: only float32, float16 and bfloat16 are supported");
    TORCH_CHECK(target.scalar_type() == at::kLong,
                "nll_loss: target must be int64");
    TORCH_CHECK(input.dim() >= 2,
                "nll_loss: input must have at least 2 dimensions (N, C, ...)");

    // ---- 维度参数 ----
    int64_t N = input.size(0);
    int64_t C = input.size(1);  // class dimension
    int64_t innerSize = 1;
    for (int64_t i = 2; i < input.dim(); ++i) {
        innerSize *= input.size(i);
    }
    int64_t totalLength = N * innerSize;

    // ---- Reduction mode ----
    int64_t reductionMode = 0;
    if (reduction == "none") {
        reductionMode = 0;
    } else if (reduction == "mean") {
        reductionMode = 1;
    } else if (reduction == "sum") {
        reductionMode = 2;
    } else {
        TORCH_CHECK(false, "nll_loss: invalid reduction mode '", reduction,
                    "', expected 'none', 'mean', or 'sum'");
    }

    // ---- 连续化 ----
    at::Tensor inputContiguous = input.contiguous();
    at::Tensor targetContiguous = target.contiguous();
    int64_t dtypeSizeVal = static_cast<int64_t>(inputContiguous.element_size());

    auto targetInt32 = targetContiguous.to(at::kInt).contiguous();

    // ---- Weight 处理 ----
    int64_t hasWeight = 0;
    at::Tensor weightContiguous;
    if (weight_opt.has_value()) {
        hasWeight = 1;
        weightContiguous = weight_opt.value().contiguous();
        TORCH_CHECK(weightContiguous.size(0) == C,
                    "nll_loss: weight must have size [C], got ", weightContiguous.sizes());
        if (weightContiguous.scalar_type() != inputContiguous.scalar_type()) {
            weightContiguous = weightContiguous.to(inputContiguous.scalar_type()).contiguous();
        }
    }

    // ---- Output 分配 ----
    int64_t outputNumElements;
    at::Tensor output;
    if (reductionMode == 0) {
        outputNumElements = totalLength;
        output = at::empty(target.sizes(),
            inputContiguous.options().dtype(inputContiguous.scalar_type()));
    } else {
        outputNumElements = 1;
        output = at::empty({},
            inputContiguous.options().dtype(inputContiguous.scalar_type()));
    }

    // ---- 平台信息 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 Tiling ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t alignElementsBlock = CACHE_LINE_BYTE_LENGTH / static_cast<int64_t>(sizeof(int32_t));
    int64_t totalLengthCoreAlign = ((totalLengthCore + alignElementsBlock - 1)
                                    / alignElementsBlock) * alignElementsBlock;
    if (totalLengthCoreAlign > totalLength) totalLengthCoreAlign = totalLength;
    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNumVal = usedCoreNum - 1;
    if (formerNumVal == 0) formerNumVal = 1;
    int64_t formerLengthVal = totalLengthCoreAlign;
    int64_t tailNumVal = usedCoreNum - formerNumVal;
    int64_t tailLengthVal = totalLength - formerNumVal * formerLengthVal;
    if (tailLengthVal < 0) tailLengthVal = 0;

    // ---- UB 级 Tiling ----
    int64_t bufferCoefficient;
    if (reductionMode == 0) {
        bufferCoefficient = 8 + 4 + static_cast<int64_t>(dtypeSizeVal) * 2;
    } else {
        bufferCoefficient = 8 + 4;
    }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / static_cast<int64_t>(sizeof(int32_t));
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < alignElements) tileLength = alignElements;

    // ---- Workspace allocation (for mean/sum) ----
    at::Tensor workspaceSum;
    at::Tensor workspaceCount;
    if (reductionMode == 1 || reductionMode == 2) {
        workspaceSum = at::empty({coreNum},
            at::TensorOptions().dtype(at::kFloat).device(input.device()));
        workspaceCount = at::empty({coreNum},
            at::TensorOptions().dtype(at::kLong).device(input.device()));
    } else {
        workspaceSum = at::empty({1},
            at::TensorOptions().dtype(at::kFloat).device(input.device()));
        workspaceCount = at::empty({1},
            at::TensorOptions().dtype(at::kLong).device(input.device()));
    }

    // ---- Tiling Data: allocate CPU tensor, fill struct, copy to NPU ----
    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(NLLLossTilingData))},
        at::TensorOptions().dtype(at::kByte).device(at::kCPU));
    auto *tiling = reinterpret_cast<NLLLossTilingData *>(tilingCpu.data_ptr());
    tiling->totalLength = totalLength;
    tiling->formerNum = formerNumVal;
    tiling->formerLength = formerLengthVal;
    tiling->tailNum = tailNumVal;
    tiling->tailLength = tailLengthVal;
    tiling->tileLength = tileLength;
    tiling->numClasses = C;
    tiling->innerSize = innerSize;
    tiling->hasWeight = hasWeight;
    tiling->ignoreIndex = ignore_index;
    tiling->reductionMode = reductionMode;
    tiling->outputNumElements = outputNumElements;
    tiling->dtypeSize = dtypeSizeVal;
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    if (!hasWeight) {
        weightContiguous = at::empty({1},
            inputContiguous.options().dtype(inputContiguous.scalar_type()));
    }

    // ---- Kernel Launch (all params must be lvalues) ----
    uint32_t blockDimLL = static_cast<uint32_t>(usedCoreNum);
    if (blockDimLL < 1) blockDimLL = 1;
    EXEC_KERNEL_CMD(nll_loss, blockDimLL,
                    inputContiguous, targetInt32, weightContiguous,
                    output, workspaceSum, workspaceCount,
                    tilingNpu);

    // ---- Post-processing for mean/sum ----
    if (reductionMode == 1 || reductionMode == 2) {
        at::Tensor sumCpu = workspaceSum.to(at::kCPU);
        at::Tensor countCpu = workspaceCount.to(at::kCPU);
        float totalSum = 0.0f;
        int64_t totalCount = 0;
        auto sumAcc = sumCpu.accessor<float, 1>();
        auto countAcc = countCpu.accessor<int64_t, 1>();
        for (int64_t i = 0; i < coreNum; ++i) {
            totalSum += sumAcc[i];
            totalCount += countAcc[i];
        }
        if (reductionMode == 1 && totalCount > 0) {
            totalSum /= static_cast<float>(totalCount);
        }
        at::Tensor cpuScalar;
        if (inputContiguous.scalar_type() == at::kFloat) {
            cpuScalar = at::scalar_tensor(static_cast<double>(totalSum),
                at::TensorOptions().dtype(at::kFloat).device(at::kCPU));
        } else if (inputContiguous.scalar_type() == at::kHalf) {
            cpuScalar = at::scalar_tensor(static_cast<double>(totalSum),
                at::TensorOptions().dtype(at::kHalf).device(at::kCPU));
        } else {
            cpuScalar = at::scalar_tensor(static_cast<double>(totalSum),
                at::TensorOptions().dtype(at::kBFloat16).device(at::kCPU));
        }
        output.copy_(cpuScalar);
    }

    return output;
}

}  // namespace ascend_kernel
