#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;
constexpr int64_t UB_ALIGN_BYTES = 32;

template<typename T>
class NLLLossKernel {
public:
    __aicore__ inline NLLLossKernel() {}
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR target, GM_ADDR weight,
                                 GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount,
                                 int64_t totalLength, int64_t formerNum, int64_t formerLength,
                                 int64_t tailNum, int64_t tailLength, int64_t tileLength,
                                 int64_t numClasses, int64_t innerSize, int64_t hasWeight,
                                 int64_t ignoreIndex, int64_t reductionMode, int64_t outNumElems,
                                 int64_t dtypeSize);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLen);
    __aicore__ inline void Compute(int64_t progress, int64_t curTileLen,
                                     float &partialSum, int64_t &validCount);
    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLen);

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> targetQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outputQueue;
    TBuf<TPosition::VECCALC> computeBuf;

    GlobalTensor<T> inputGm;
    GlobalTensor<int32_t> targetGm;
    GlobalTensor<T> weightGm;
    GlobalTensor<T> outputGm;
    GlobalTensor<float> workspaceSumGm;
    GlobalTensor<int64_t> workspaceCountGm;

    int64_t totalLength_, formerNum_, formerLength_;
    int64_t tailNum_, tailLength_, tileLength_;
    int64_t numClasses_, innerSize_;
    int64_t hasWeight_, ignoreIndex_;
    int64_t reductionMode_, outNumElems_, dtypeSize_;

    int64_t coreOffset_;
    int64_t coreLength_;
};

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Init(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount,
    int64_t totalLength, int64_t formerNum, int64_t formerLength,
    int64_t tailNum, int64_t tailLength, int64_t tileLength,
    int64_t numClasses, int64_t innerSize, int64_t hasWeight,
    int64_t ignoreIndex, int64_t reductionMode, int64_t outNumElems,
    int64_t dtypeSize) {

    totalLength_ = totalLength; formerNum_ = formerNum;
    formerLength_ = formerLength; tailNum_ = tailNum; tailLength_ = tailLength;
    tileLength_ = tileLength; numClasses_ = numClasses; innerSize_ = innerSize;
    hasWeight_ = hasWeight; ignoreIndex_ = ignoreIndex;
    reductionMode_ = reductionMode; outNumElems_ = outNumElems; dtypeSize_ = dtypeSize;

    int64_t blockIdx = GetBlockIdx();
    if (blockIdx < formerNum_) {
        coreOffset_ = blockIdx * formerLength_;
        coreLength_ = formerLength_;
    } else {
        int64_t tailIdx = blockIdx - formerNum_;
        coreOffset_ = formerNum_ * formerLength_ + tailIdx * tailLength_;
        coreLength_ = tailLength_;
    }

    int64_t totInput = numClasses_ * innerSize_ * (totalLength_ / innerSize_);
    inputGm.SetGlobalBuffer((__gm__ T*)input, totInput);
    targetGm.SetGlobalBuffer((__gm__ int32_t*)target, totalLength_);
    if (hasWeight_) weightGm.SetGlobalBuffer((__gm__ T*)weight, numClasses_);
    outputGm.SetGlobalBuffer((__gm__ T*)output, outNumElems_);
    if (reductionMode_ == 1 || reductionMode_ == 2) {
        workspaceSumGm.SetGlobalBuffer((__gm__ float*)wsSum);
        workspaceCountGm.SetGlobalBuffer((__gm__ int64_t*)wsCount);
    }

    pipe.InitBuffer(targetQueue, BUFFER_NUM, tileLength_ * sizeof(int32_t));
    pipe.InitBuffer(computeBuf, tileLength_ * sizeof(float));
    if (reductionMode_ == 0)
        pipe.InitBuffer(outputQueue, BUFFER_NUM, tileLength_ * sizeof(T));
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Process() {
    if (coreLength_ <= 0) return;

    float partialSum = 0.0f;
    int64_t validCount = 0;
    int64_t tileNum = (coreLength_ + tileLength_ - 1) / tileLength_;

    for (int64_t i = 0; i < tileNum; ++i) {
        int64_t cur = (i == tileNum - 1) ? coreLength_ - (tileNum - 1) * tileLength_ : tileLength_;
        CopyIn(i, cur);
        Compute(i, cur, partialSum, validCount);
        if (reductionMode_ == 0) CopyOut(i, cur);
    }

    if (reductionMode_ == 1 || reductionMode_ == 2) {
        int64_t blockIdx = GetBlockIdx();
        workspaceSumGm.SetValue(blockIdx, partialSum);
        workspaceCountGm.SetValue(blockIdx, validCount);
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CopyIn(int64_t progress, int64_t curTileLen) {
    LocalTensor<int32_t> tgt = targetQueue.AllocTensor<int32_t>();
    int64_t start = coreOffset_ + progress * tileLength_;
    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(curTileLen * sizeof(int32_t));
    cp.srcStride = 0;
    cp.dstStride = 0;
    DataCopyPadExtParams<int32_t> pp;
    pp.isPad = false;
    DataCopyPad(tgt, targetGm[start], cp, pp);
    targetQueue.EnQue(tgt);
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Compute(
    int64_t progress, int64_t curTileLen, float &partialSum, int64_t &validCount) {

    LocalTensor<int32_t> tgt = targetQueue.DeQue<int32_t>();
    LocalTensor<float> comp = computeBuf.Get<float>();

    for (int64_t e = 0; e < curTileLen; ++e) {
        int32_t cls = tgt.GetValue(e);
        if (cls == static_cast<int32_t>(ignoreIndex_)) {
            if (reductionMode_ == 0) comp.SetValue(e, 0.0f);
            continue;
        }
        int64_t gIdx = coreOffset_ + progress * tileLength_ + e;
        int64_t n = gIdx / innerSize_;
        int64_t r = gIdx % innerSize_;
        int64_t off = n * numClasses_ * innerSize_ + static_cast<int64_t>(cls) * innerSize_ + r;

        float val;
        if constexpr (sizeof(T) == sizeof(float))
            val = inputGm.GetValue(off);
        else
            val = static_cast<float>(inputGm.GetValue(off));
        val = -val;

        if (hasWeight_) {
            if constexpr (sizeof(T) == sizeof(float))
                val *= weightGm.GetValue(cls);
            else
                val *= static_cast<float>(weightGm.GetValue(cls));
        }
        if (reductionMode_ == 0) comp.SetValue(e, val);
        else partialSum += val;
        validCount++;
    }
    targetQueue.FreeTensor(tgt);

    if (reductionMode_ == 0) {
        if constexpr (sizeof(T) == sizeof(float)) {
            LocalTensor<float> out = outputQueue.AllocTensor<float>();
            for (int64_t e = 0; e < curTileLen; ++e) out.SetValue(e, comp.GetValue(e));
            outputQueue.EnQue(out);
        } else {
            LocalTensor<T> out = outputQueue.AllocTensor<T>();
            Cast(out, comp, AscendC::RoundMode::CAST_ROUND, curTileLen);
            outputQueue.EnQue(out);
        }
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CopyOut(int64_t progress, int64_t curTileLen) {
    LocalTensor<T> out = outputQueue.DeQue<T>();
    int64_t start = coreOffset_ + progress * tileLength_;
    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(curTileLen * sizeof(T));
    cp.srcStride = 0;
    cp.dstStride = 0;
    DataCopyPad(outputGm[start], out, cp);
    outputQueue.FreeTensor(out);
}

extern "C" __global__ __aicore__ void nll_loss(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount,
    int64_t totalLength, int64_t formerNum, int64_t formerLength,
    int64_t tailNum, int64_t tailLength, int64_t tileLength,
    int64_t numClasses, int64_t innerSize, int64_t hasWeight,
    int64_t ignoreIndex, int64_t reductionMode, int64_t outNumElems,
    int64_t dtypeSize) {
    if (dtypeSize == 4) {
        NLLLossKernel<float> op;
        op.Init(input, target, weight, output, wsSum, wsCount,
                totalLength, formerNum, formerLength, tailNum, tailLength, tileLength,
                numClasses, innerSize, hasWeight, ignoreIndex, reductionMode,
                outNumElems, dtypeSize);
        op.Process();
    } else if (dtypeSize == 2) {
        NLLLossKernel<half> op;
        op.Init(input, target, weight, output, wsSum, wsCount,
                totalLength, formerNum, formerLength, tailNum, tailLength, tileLength,
                numClasses, innerSize, hasWeight, ignoreIndex, reductionMode,
                outNumElems, dtypeSize);
        op.Process();
    }
}
