#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

struct Tiling {
    int64_t totalLength, formerNum, formerLength, tailNum, tailLength, tileLength;
    int64_t numClasses, innerSize, hasWeight, ignoreIndex;
    int64_t reductionMode, outputNumElements, dtypeSize;
};

template<typename T>
class NLLLossKernel {
public:
    __aicore__ inline NLLLossKernel() {}
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR target, GM_ADDR weight,
                                 GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount, Tiling t);
    __aicore__ inline void Process();
private:
    __aicore__ inline void CopyIn(int64_t p, int64_t cur);
    __aicore__ inline void Compute(int64_t p, int64_t cur, float &ps, int64_t &vc);
    __aicore__ inline void CopyOut(int64_t p, int64_t cur);

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> tq;
    TQue<TPosition::VECOUT, BUFFER_NUM> oq;
    TBuf<TPosition::VECCALC> cb;

    GlobalTensor<T> ig, wg, og;
    GlobalTensor<int32_t> tg;
    GlobalTensor<float> wsg;
    GlobalTensor<int64_t> wcg;

    Tiling t_;
    int64_t off_, len_;
};

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Init(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount, Tiling t) {

    t_ = t;
    int64_t bi = GetBlockIdx();
    if (bi < t_.formerNum) {
        off_ = bi * t_.formerLength;
        len_ = t_.formerLength;
    } else {
        int64_t ti = bi - t_.formerNum;
        off_ = t_.formerNum * t_.formerLength + ti * t_.tailLength;
        len_ = t_.tailLength;
    }

    ig.SetGlobalBuffer((__gm__ T*)input,
        t_.numClasses * t_.innerSize * (t_.totalLength / t_.innerSize));
    tg.SetGlobalBuffer((__gm__ int32_t*)target, t_.totalLength);
    if (t_.hasWeight) wg.SetGlobalBuffer((__gm__ T*)weight, t_.numClasses);
    og.SetGlobalBuffer((__gm__ T*)output, t_.outputNumElements);
    if (t_.reductionMode == 1 || t_.reductionMode == 2) {
        wsg.SetGlobalBuffer((__gm__ float*)wsSum);
        wcg.SetGlobalBuffer((__gm__ int64_t*)wsCount);
    }

    pipe.InitBuffer(tq, BUFFER_NUM, t_.tileLength * sizeof(int32_t));
    pipe.InitBuffer(cb, t_.tileLength * sizeof(float));
    if (t_.reductionMode == 0)
        pipe.InitBuffer(oq, BUFFER_NUM, t_.tileLength * sizeof(T));
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Process() {
    if (len_ <= 0) return;
    float ps = 0.0f;
    int64_t vc = 0;
    int64_t tn = (len_ + t_.tileLength - 1) / t_.tileLength;
    for (int64_t i = 0; i < tn; ++i) {
        int64_t cur = (i == tn - 1) ? len_ - (tn - 1) * t_.tileLength : t_.tileLength;
        CopyIn(i, cur);
        Compute(i, cur, ps, vc);
        if (t_.reductionMode == 0) CopyOut(i, cur);
    }
    if (t_.reductionMode == 1 || t_.reductionMode == 2) {
        int64_t bi = GetBlockIdx();
        wsg.SetValue(bi, ps);
        wcg.SetValue(bi, vc);
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CopyIn(int64_t p, int64_t cur) {
    LocalTensor<int32_t> tl = tq.AllocTensor<int32_t>();
    int64_t st = off_ + p * t_.tileLength;
    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(cur * sizeof(int32_t));
    cp.srcStride = 0; cp.dstStride = 0;
    DataCopyPadExtParams<int32_t> pp;
    pp.isPad = false;
    DataCopyPad(tl, tg[st], cp, pp);
    tq.EnQue(tl);
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Compute(int64_t p, int64_t cur, float &ps, int64_t &vc) {
    LocalTensor<int32_t> tl = tq.DeQue<int32_t>();
    LocalTensor<float> cl = cb.Get<float>();

    for (int64_t e = 0; e < cur; ++e) {
        int32_t cIdx = tl.GetValue(e);
        if (cIdx == static_cast<int32_t>(t_.ignoreIndex)) {
            if (t_.reductionMode == 0) cl.SetValue(e, 0.0f);
            continue;
        }
        int64_t g = off_ + p * t_.tileLength + e;
        int64_t n = g / t_.innerSize, r = g % t_.innerSize;
        int64_t off = n * t_.numClasses * t_.innerSize + static_cast<int64_t>(cIdx) * t_.innerSize + r;
        float val = ig.GetValue(off);
        val = -val;
        if (t_.hasWeight) val *= static_cast<float>(wg.GetValue(cIdx));
        if (t_.reductionMode == 0) cl.SetValue(e, val);
        else ps += val;
        vc++;
    }
    tq.FreeTensor(tl);

    if (t_.reductionMode == 0) {
        LocalTensor<T> ol = oq.AllocTensor<T>();
        if constexpr (sizeof(T) == sizeof(float)) {
            for (int64_t e = 0; e < cur; ++e) ol.SetValue(e, static_cast<T>(cl.GetValue(e)));
        } else {
            Cast(ol, cl, AscendC::RoundMode::CAST_ROUND, cur);
        }
        oq.EnQue(ol);
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CopyOut(int64_t p, int64_t cur) {
    LocalTensor<T> ol = oq.DeQue<T>();
    int64_t st = off_ + p * t_.tileLength;
    DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(cur * sizeof(T));
    cp.srcStride = 0; cp.dstStride = 0;
    DataCopyPad(og[st], ol, cp);
    oq.FreeTensor(ol);
}

extern "C" __global__ __aicore__ void nll_loss(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount, Tiling t) {
    if (t.dtypeSize == 4) {
        NLLLossKernel<float> op;
        op.Init(input, target, weight, output, wsSum, wsCount, t);
        op.Process();
    } else if (t.dtypeSize == 2) {
        NLLLossKernel<half> op;
        op.Init(input, target, weight, output, wsSum, wsCount, t);
        op.Process();
    }
}
