#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_nll_loss.h"
#include <torch/extension.h>

/* Must match the Tiling struct in op_kernel/nll_loss.cpp exactly */
struct Tiling {
    int64_t totalLength, formerNum, formerLength, tailNum, tailLength, tileLength;
    int64_t numClasses, innerSize, hasWeight, ignoreIndex;
    int64_t reductionMode, outputNumElements, dtypeSize;
};

namespace ascend_kernel {

namespace {
constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
}  // namespace

at::Tensor nll_loss(
    const at::Tensor &input,
    const at::Tensor &target,
    const c10::optional<at::Tensor> &weight_opt,
    int64_t ignore_index,
    c10::string_view reduction) {

    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
                "nll_loss: input must be on NPU");
    TORCH_CHECK(target.device().type() == at::DeviceType::PrivateUse1,
                "nll_loss: target must be on NPU");
    TORCH_CHECK(input.scalar_type() == at::kFloat ||
                input.scalar_type() == at::kHalf ||
                input.scalar_type() == at::kBFloat16,
                "nll_loss: only float32/16/bf16 supported");
    TORCH_CHECK(target.scalar_type() == at::kLong,
                "nll_loss: target must be int64");
    TORCH_CHECK(input.dim() >= 2,
                "nll_loss: input must have at least 2 dims");

    int64_t N = input.size(0);
    int64_t C = input.size(1);
    int64_t innerSize = 1;
    for (int64_t i = 2; i < input.dim(); ++i) innerSize *= input.size(i);
    int64_t totalLength = N * innerSize;

    int64_t reductionMode = 0;
    if (reduction == "none") reductionMode = 0;
    else if (reduction == "mean") reductionMode = 1;
    else if (reduction == "sum") reductionMode = 2;
    else TORCH_CHECK(false, "nll_loss: invalid reduction");

    at::Tensor in = input.contiguous();
    at::Tensor tgt = target.contiguous();
    int64_t dtypeSz = static_cast<int64_t>(in.element_size());
    at::Tensor tgt32 = tgt.to(at::kInt).contiguous();

    int64_t hasW = 0;
    at::Tensor wCont;
    if (weight_opt.has_value()) {
        hasW = 1;
        wCont = weight_opt.value().contiguous();
        if (wCont.scalar_type() != in.scalar_type())
            wCont = wCont.to(in.scalar_type()).contiguous();
    }

    int64_t outNE;
    at::Tensor out;
    if (reductionMode == 0) {
        outNE = totalLength;
        out = at::empty(tgt.sizes(), in.options().dtype(in.scalar_type()));
    } else {
        outNE = 1;
        out = at::empty({}, in.options().dtype(in.scalar_type()));
    }

    auto plat = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t nCore = static_cast<int64_t>(plat->GetCoreNumAiv());
    uint64_t ubSz;
    plat->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSz);
    int64_t ubLim = static_cast<int64_t>(ubSz);

    // Block tiling
    int64_t coreLen = (totalLength + nCore - 1) / nCore;
    int64_t alE = CACHE_LINE_BYTE_LENGTH / static_cast<int64_t>(sizeof(int32_t));
    int64_t coreLenAl = ((coreLen + alE - 1) / alE) * alE;
    if (coreLenAl > totalLength) coreLenAl = totalLength;
    int64_t nUsed = (totalLength + coreLenAl - 1) / coreLenAl;
    if (nUsed < 1) nUsed = 1;
    int64_t fNum = nUsed - 1;
    if (fNum == 0) fNum = 1;
    int64_t fLen = coreLenAl;
    int64_t tNum = nUsed - fNum;
    int64_t tLen = totalLength - fNum * fLen;
    if (tLen < 0) tLen = 0;

    // UB tiling
    int64_t bufCoef = reductionMode == 0 ? (8 + 4 + dtypeSz * 2) : (8 + 4);
    int64_t maxTE = ubLim / bufCoef;
    int64_t alUb = 32 / static_cast<int64_t>(sizeof(int32_t));
    int64_t tLenU = (maxTE / alUb) * alUb;
    if (tLenU < alUb) tLenU = alUb;

    // Workspace
    at::Tensor wsSum, wsCnt;
    if (reductionMode == 1 || reductionMode == 2) {
        wsSum = at::empty({nCore}, at::TensorOptions().dtype(at::kFloat).device(in.device()));
        wsCnt = at::empty({nCore}, at::TensorOptions().dtype(at::kLong).device(in.device()));
    } else {
        wsSum = at::empty({1}, at::TensorOptions().dtype(at::kFloat).device(in.device()));
        wsCnt = at::empty({1}, at::TensorOptions().dtype(at::kLong).device(in.device()));
    }
    if (!hasW) wCont = at::empty({1}, in.options().dtype(in.scalar_type()));

    // Tiling struct via tensor on NPU
    at::Tensor tilingCpu = at::empty({static_cast<int64_t>(sizeof(Tiling))},
        at::TensorOptions().dtype(at::kByte).device(at::kCPU));
    auto *td = reinterpret_cast<Tiling *>(tilingCpu.data_ptr());
    td->totalLength = totalLength; td->formerNum = fNum; td->formerLength = fLen;
    td->tailNum = tNum; td->tailLength = tLen; td->tileLength = tLenU;
    td->numClasses = C; td->innerSize = innerSize; td->hasWeight = hasW;
    td->ignoreIndex = ignore_index; td->reductionMode = reductionMode;
    td->outputNumElements = outNE; td->dtypeSize = dtypeSz;
    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Launch
    uint32_t bd = static_cast<uint32_t>(nUsed);
    if (bd < 1) bd = 1;
    EXEC_KERNEL_CMD(nll_loss, bd, in, tgt32, wCont, out, wsSum, wsCnt, tilingNpu);

    // Post-processing for mean/sum
    if (reductionMode == 1 || reductionMode == 2) {
        at::Tensor sC = wsSum.to(at::kCPU);
        at::Tensor cC = wsCnt.to(at::kCPU);
        float totS = 0.0f;
        int64_t totC = 0;
        auto sa = sC.accessor<float, 1>();
        auto ca = cC.accessor<int64_t, 1>();
        for (int64_t i = 0; i < nCore; ++i) { totS += sa[i]; totC += ca[i]; }
        if (reductionMode == 1 && totC > 0) totS /= static_cast<float>(totC);
        at::Tensor cpuS;
        if (in.scalar_type() == at::kFloat)
            cpuS = at::scalar_tensor(static_cast<double>(totS),
                at::TensorOptions().dtype(at::kFloat).device(at::kCPU));
        else if (in.scalar_type() == at::kHalf)
            cpuS = at::scalar_tensor(static_cast<double>(totS),
                at::TensorOptions().dtype(at::kHalf).device(at::kCPU));
        else
            cpuS = at::scalar_tensor(static_cast<double>(totS),
                at::TensorOptions().dtype(at::kBFloat16).device(at::kCPU));
        out.copy_(cpuS);
    }
    return out;
}

}  // namespace ascend_kernel
