#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

struct NLossTiling {
    int64_t totalLength, formerNum, formerLength, tailNum, tailLength, tileLength;
    int64_t numClasses, innerSize, hasWeight, ignoreIndex;
    int64_t reductionMode, outputNumElements, dtypeSize;
};

template<typename T>
class NLLLossKernel {
public:
    __aicore__ inline NLLLossKernel() {}
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR target, GM_ADDR weight,
                                 GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount,
                                 NLossTiling t);
    __aicore__ inline void Process();
private:
    __aicore__ inline void CopyIn(int64_t p, int64_t cur);
    __aicore__ inline void Compute(int64_t p, int64_t cur, float &ps, int64_t &vc);
    __aicore__ inline void CopyOut(int64_t p, int64_t cur);

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> tq;
    TQue<TPosition::VECOUT, BUFFER_NUM> oq;
    TBuf<TPosition::VECCALC> cb;

    GlobalTensor<T> ig, wg, og;
    GlobalTensor<int32_t> tg;
    GlobalTensor<float> wsg;
    GlobalTensor<int64_t> wcg;

    NLossTiling td_;
    int64_t off_, len_;
};

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Init(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount, NLossTiling t) {
    td_ = t;
    int64_t bi = GetBlockIdx();
    if (bi < td_.formerNum) { off_ = bi * td_.formerLength; len_ = td_.formerLength; }
    else { int64_t ti = bi - td_.formerNum; off_ = td_.formerNum * td_.formerLength + ti * td_.tailLength; len_ = td_.tailLength; }

    ig.SetGlobalBuffer((__gm__ T*)input, td_.numClasses * td_.innerSize * (td_.totalLength / td_.innerSize));
    tg.SetGlobalBuffer((__gm__ int32_t*)target, td_.totalLength);
    if (td_.hasWeight) wg.SetGlobalBuffer((__gm__ T*)weight, td_.numClasses);
    og.SetGlobalBuffer((__gm__ T*)output, td_.outputNumElements);
    if (td_.reductionMode == 1 || td_.reductionMode == 2) {
        wsg.SetGlobalBuffer((__gm__ float*)wsSum);
        wcg.SetGlobalBuffer((__gm__ int64_t*)wsCount);
    }
    pipe.InitBuffer(tq, BUFFER_NUM, td_.tileLength * sizeof(int32_t));
    pipe.InitBuffer(cb, td_.tileLength * sizeof(float));
    if (td_.reductionMode == 0) pipe.InitBuffer(oq, BUFFER_NUM, td_.tileLength * sizeof(T));
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Process() {
    if (len_ <= 0) return;
    float ps = 0.0f; int64_t vc = 0;
    int64_t tn = (len_ + td_.tileLength - 1) / td_.tileLength;
    for (int64_t i = 0; i < tn; ++i) {
        int64_t cur = (i == tn - 1) ? len_ - (tn - 1) * td_.tileLength : td_.tileLength;
        CopyIn(i, cur); Compute(i, cur, ps, vc);
        if (td_.reductionMode == 0) CopyOut(i, cur);
    }
    if (td_.reductionMode == 1 || td_.reductionMode == 2) {
        int64_t bi = GetBlockIdx();
        wsg.SetValue(bi, ps); wcg.SetValue(bi, vc);
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CopyIn(int64_t p, int64_t cur) {
    LocalTensor<int32_t> tl = tq.AllocTensor<int32_t>();
    int64_t st = off_ + p * td_.tileLength;
    DataCopyExtParams cp; cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(cur * sizeof(int32_t));
    cp.srcStride = 0; cp.dstStride = 0;
    DataCopyPadExtParams<int32_t> pp; pp.isPad = false;
    DataCopyPad(tl, tg[st], cp, pp); tq.EnQue(tl);
