#include "kernel_operator.h"
using namespace AscendC;
constexpr int64_t BN = 2;

struct NLossT {
    int64_t totalLength, formerNum, formerLength, tailNum, tailLength, tileLength;
    int64_t numClasses, innerSize, hasWeight, ignoreIndex;
    int64_t reductionMode, outputNumElements, dtypeSize;
};

template<typename T>
class NLLLossKernel {
public:
    __aicore__ inline NLLLossKernel() {}
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR target, GM_ADDR weight,
                                 GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount,
                                 GM_ADDR tilingGm);
    __aicore__ inline void Process();
private:
    __aicore__ inline void CI(int64_t p, int64_t cur);
    __aicore__ inline void CC(int64_t p, int64_t cur, float &ps, int64_t &vc);
    __aicore__ inline void CO(int64_t p, int64_t cur);
    TPipe pipe;
    TQue<TPosition::VECIN, BN> tq;
    TQue<TPosition::VECOUT, BN> oq;
    TBuf<TPosition::VECCALC> cb;
    GlobalTensor<T> ig, wg, og;
    GlobalTensor<int32_t> tg;
    GlobalTensor<float> wsg;
    GlobalTensor<int64_t> wcg;
    NLossT d;
    int64_t o_, l_;
};

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Init(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount, GM_ADDR tilingGm) {

    // Copy tiling struct from GM to local
    d = *reinterpret_cast<__gm__ NLossT*>(tilingGm);

    int64_t bi = GetBlockIdx();
    if (bi < d.formerNum) { o_ = bi * d.formerLength; l_ = d.formerLength; }
    else { int64_t ti = bi - d.formerNum; o_ = d.formerNum * d.formerLength + ti * d.tailLength; l_ = d.tailLength; }

    ig.SetGlobalBuffer((__gm__ T*)input, d.numClasses * d.innerSize * (d.totalLength / d.innerSize));
    tg.SetGlobalBuffer((__gm__ int32_t*)target, d.totalLength);
    if (d.hasWeight) wg.SetGlobalBuffer((__gm__ T*)weight, d.numClasses);
    og.SetGlobalBuffer((__gm__ T*)output, d.outputNumElements);
    if (d.reductionMode == 1 || d.reductionMode == 2) {
        wsg.SetGlobalBuffer((__gm__ float*)wsSum);
        wcg.SetGlobalBuffer((__gm__ int64_t*)wsCount);
    }
    pipe.InitBuffer(tq, BN, d.tileLength * sizeof(int32_t));
    pipe.InitBuffer(cb, d.tileLength * sizeof(float));
    if (d.reductionMode == 0) pipe.InitBuffer(oq, BN, d.tileLength * sizeof(T));
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Process() {
    if (l_ <= 0) return;
    float ps = 0.0f; int64_t vc = 0;
    int64_t tn = (l_ + d.tileLength - 1) / d.tileLength;
    for (int64_t i = 0; i < tn; ++i) {
        int64_t cur = (i == tn - 1) ? l_ - (tn - 1) * d.tileLength : d.tileLength;
        CI(i, cur); CC(i, cur, ps, vc);
        if (d.reductionMode == 0) CO(i, cur);
    }
    if (d.reductionMode == 1 || d.reductionMode == 2) {
        int64_t bi = GetBlockIdx();
        wsg.SetValue(bi, ps); wcg.SetValue(bi, vc);
    }
}

