#include "kernel_operator.h"
using namespace AscendC;
constexpr int64_t BN = 2;

template<typename T>
class NLLLossKernel {
public:
    __aicore__ inline NLLLossKernel() {}
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR target, GM_ADDR weight,
                                 GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount,
                                 GM_ADDR tilingGm);
    __aicore__ inline void Process();
private:
    __aicore__ inline void CI(int64_t p, int64_t cur);
    __aicore__ inline void CC(int64_t p, int64_t cur, float &ps, int64_t &vc);
    __aicore__ inline void CO(int64_t p, int64_t cur);
    TPipe pipe;
    TQue<TPosition::VECIN, BN> tq;
    TQue<TPosition::VECOUT, BN> oq;
    TBuf<TPosition::VECCALC> cb;
    GlobalTensor<T> ig, wg, og;
    GlobalTensor<int32_t> tg;
    GlobalTensor<float> wsg;
    GlobalTensor<int64_t> wcg;
    GlobalTensor<int64_t> tilingG;
    int64_t o_, l_, tl_, nc_, is_, hi_, igi_, rm_, one_, ds_;
};

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Init(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount, GM_ADDR tilingGm) {

    tilingG.SetGlobalBuffer((__gm__ int64_t*)tilingGm, 13);
    int64_t tl = tilingG.GetValue(0);   // totalLength
    int64_t fn = tilingG.GetValue(1);   // formerNum
    int64_t fl = tilingG.GetValue(2);   // formerLength
    int64_t tn = tilingG.GetValue(3);   // tailNum
    int64_t tlen = tilingG.GetValue(4);  // tailLength
    tl_ = tilingG.GetValue(5);          // tileLength
    nc_ = tilingG.GetValue(6);          // numClasses
    is_ = tilingG.GetValue(7);          // innerSize
    hi_ = tilingG.GetValue(8);          // hasWeight
    igi_ = tilingG.GetValue(9);         // ignoreIndex
    rm_ = tilingG.GetValue(10);         // reductionMode
    one_ = tilingG.GetValue(11);        // outputNumElements
    ds_ = tilingG.GetValue(12);         // dtypeSize

    int64_t bi = GetBlockIdx();
    if (bi < fn) { o_ = bi * fl; l_ = fl; }
    else { int64_t ti = bi - fn; o_ = fn * fl + ti * tlen; l_ = tlen; }

    ig.SetGlobalBuffer((__gm__ T*)input, nc_ * is_ * (tl / is_));
    tg.SetGlobalBuffer((__gm__ int32_t*)target, tl);
    if (hi_) wg.SetGlobalBuffer((__gm__ T*)weight, nc_);
    og.SetGlobalBuffer((__gm__ T*)output, one_);
    wsg.SetGlobalBuffer((__gm__ float*)wsSum);
    wcg.SetGlobalBuffer((__gm__ int64_t*)wsCount);

    pipe.InitBuffer(tq, BN, tl_ * sizeof(int32_t));
    pipe.InitBuffer(cb, tl_ * sizeof(float));
    if (rm_ == 0) pipe.InitBuffer(oq, BN, tl_ * sizeof(T));
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::Process() {
    if (l_ <= 0) return;
    float ps = 0.0f; int64_t vc = 0;
    int64_t tn = (l_ + tl_ - 1) / tl_;
    for (int64_t i = 0; i < tn; ++i) {
        int64_t cur = (i == tn - 1) ? l_ - (tn - 1) * tl_ : tl_;
        CI(i, cur); CC(i, cur, ps, vc);
        if (rm_ == 0) CO(i, cur);
    }
    if (rm_ == 1 || rm_ == 2) {
        int64_t bi = GetBlockIdx();
        // Write partial sum directly to output[bi] as float
        LocalTensor<T> oL = pipe.GetBuffer<T>(oq, 1);
        oL.SetValue(0, static_cast<T>(ps));
        DataCopyExtParams cp; cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(sizeof(T));
        cp.srcStride = 0; cp.dstStride = 0;
        DataCopyPad(og[bi], oL, cp);
        wcg.SetValue(bi, vc);
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CI(int64_t p, int64_t cur) {
    LocalTensor<int32_t> tL = tq.AllocTensor<int32_t>();
    int64_t st = o_ + p * tl_;
    DataCopyExtParams cp; cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(cur * sizeof(int32_t));
    cp.srcStride = 0; cp.dstStride = 0;
    DataCopyPadExtParams<int32_t> pp; pp.isPad = false;
    DataCopyPad(tL, tg[st], cp, pp); tq.EnQue(tL);
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CC(int64_t p, int64_t cur, float &ps, int64_t &vc) {
    LocalTensor<int32_t> tL = tq.DeQue<int32_t>();
    LocalTensor<float> cL = cb.Get<float>();
    for (int64_t e = 0; e < cur; ++e) {
        int32_t cI = tL.GetValue(e);
        if (cI == static_cast<int32_t>(igi_)) {
            if (rm_ == 0) cL.SetValue(e, 0.0f);
            continue;
        }
        int64_t g = o_ + p * tl_ + e;
        int64_t n = g / is_, r = g % is_;
        int64_t off = n * nc_ * is_ + static_cast<int64_t>(cI) * is_ + r;
        float val = ig.GetValue(off); val = -val;
        if (hi_) val *= static_cast<float>(wg.GetValue(cI));
        if (rm_ == 0) cL.SetValue(e, val); else ps += val;
        vc++;
    }
    tq.FreeTensor(tL);
    if (rm_ == 0) {
        LocalTensor<T> oL = oq.AllocTensor<T>();
        if constexpr (sizeof(T) == sizeof(float)) {
            for (int64_t e = 0; e < cur; ++e) oL.SetValue(e, static_cast<T>(cL.GetValue(e)));
        } else { Cast(oL, cL, AscendC::RoundMode::CAST_ROUND, cur); }
        oq.EnQue(oL);
    }
}

template<typename T>
__aicore__ inline void NLLLossKernel<T>::CO(int64_t p, int64_t cur) {
    LocalTensor<T> oL = oq.DeQue<T>();
    int64_t st = o_ + p * tl_;
    DataCopyExtParams cp; cp.blockCount = 1;
    cp.blockLen = static_cast<uint32_t>(cur * sizeof(T));
    cp.srcStride = 0; cp.dstStride = 0;
    DataCopyPad(og[st], oL, cp); oq.FreeTensor(oL);
}

extern "C" __global__ __aicore__ void nll_loss(
    GM_ADDR input, GM_ADDR target, GM_ADDR weight,
    GM_ADDR output, GM_ADDR wsSum, GM_ADDR wsCount, GM_ADDR tilingGm) {
    GlobalTensor<int64_t> tmpG;
    tmpG.SetGlobalBuffer((__gm__ int64_t*)tilingGm, 13);
    int64_t ds = tmpG.GetValue(12);
    if (ds == 4) {
        NLLLossKernel<float> op;
        op.Init(input, target, weight, output, wsSum, wsCount, tilingGm); op.Process();
    } else if (ds == 2) {
        NLLLossKernel<half> op;
        op.Init(input, target, weight, output, wsSum, wsCount, tilingGm); op.Process();
    }
}
