#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_nll_loss.h"
#include <torch/extension.h>

struct NLossTiling {
    int64_t totalLength, formerNum, formerLength, tailNum, tailLength, tileLength;
    int64_t numClasses, innerSize, hasWeight, ignoreIndex;
    int64_t reductionMode, outputNumElements, dtypeSize;
};

namespace ascend_kernel {
namespace {
constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
}

at::Tensor nll_loss(
    const at::Tensor &input, const at::Tensor &target,
    const c10::optional<at::Tensor> &weight_opt,
    int64_t ignore_index, c10::string_view reduction) {

    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1, "nll_loss: input must be on NPU");
    TORCH_CHECK(target.device().type() == at::DeviceType::PrivateUse1, "nll_loss: target must be on NPU");
    TORCH_CHECK(input.scalar_type() == at::kFloat || input.scalar_type() == at::kHalf ||
                input.scalar_type() == at::kBFloat16, "nll_loss: only float32/16/bf16");
    TORCH_CHECK(target.scalar_type() == at::kLong, "nll_loss: target must be int64");
    TORCH_CHECK(input.dim() >= 2, "nll_loss: input must have at least 2 dims");

    int64_t N = input.size(0), C = input.size(1);
    int64_t innerSize = 1;
    for (int64_t i = 2; i < input.dim(); ++i) innerSize *= input.size(i);
    int64_t totalLength = N * innerSize;

    int64_t rm = 0;
    if (reduction == "none") rm = 0;
    else if (reduction == "mean") rm = 1;
    else if (reduction == "sum") rm = 2;
    else TORCH_CHECK(false, "nll_loss: invalid reduction");

    at::Tensor in = input.contiguous();
    at::Tensor tgt = target.contiguous();
    int64_t ds = static_cast<int64_t>(in.element_size());
    at::Tensor tgt32 = tgt.to(at::kInt).contiguous();

    int64_t hw = 0;
    at::Tensor wc;
    if (weight_opt.has_value()) {
        hw = 1; wc = weight_opt.value().contiguous();
        if (wc.scalar_type() != in.scalar_type()) wc = wc.to(in.scalar_type()).contiguous();
    }

    auto plat = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t nC = static_cast<int64_t>(plat->GetCoreNumAiv());
    uint64_t ubSz;
    plat->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSz);
    int64_t ub = static_cast<int64_t>(ubSz);

    int64_t cl = (totalLength + nC - 1) / nC;
    int64_t ae = CACHE_LINE_BYTE_LENGTH / static_cast<int64_t>(sizeof(int32_t));
    int64_t cla = ((cl + ae - 1) / ae) * ae;
    if (cla > totalLength) cla = totalLength;
    int64_t nU = (totalLength + cla - 1) / cla; if (nU < 1) nU = 1;
    int64_t fN = nU - 1; if (fN == 0) fN = 1;
    int64_t fL = cla;
    int64_t tN = nU - fN;
    int64_t tL = totalLength - fN * fL; if (tL < 0) tL = 0;

    int64_t bc = rm == 0 ? (8 + 4 + ds * 2) : (8 + 4);
    int64_t mte = ub / bc;
    int64_t au = 32 / static_cast<int64_t>(sizeof(int32_t));
    int64_t tL2 = (mte / au) * au; if (tL2 < au) tL2 = au;

    // Output tensor
    int64_t outNE;
    at::Tensor out;
    if (rm == 0) {
        outNE = totalLength;
        out = at::empty(tgt.sizes(), in.options().dtype(in.scalar_type()));
    } else {
        outNE = 1;
        out = at::empty({}, in.options().dtype(in.scalar_type()));
    }

    // Workspace: float partial sum + int64 count per core
    at::Tensor wsF = at::zeros({nC}, at::TensorOptions().dtype(at::kFloat).device(in.device()));
    at::Tensor wsI = at::zeros({nC}, at::TensorOptions().dtype(at::kLong).device(in.device()));

    if (!hw) wc = at::empty({1}, in.options().dtype(in.scalar_type()));

    at::Tensor tCpu = at::empty({static_cast<int64_t>(sizeof(NLossTiling))},
        at::TensorOptions().dtype(at::kByte).device(at::kCPU));
    auto *td = reinterpret_cast<NLossTiling *>(tCpu.data_ptr());
    td->totalLength = totalLength; td->formerNum = fN; td->formerLength = fL;
    td->tailNum = tN; td->tailLength = tL; td->tileLength = tL2;
    td->numClasses = C; td->innerSize = innerSize; td->hasWeight = hw;
    td->ignoreIndex = ignore_index; td->reductionMode = rm;
    td->outputNumElements = outNE; td->dtypeSize = ds;
    at::Tensor tNpu = tCpu.to(at::kPrivateUse1);

    uint32_t bd = static_cast<uint32_t>(nU); if (bd < 1) bd = 1;

    // Synchronize before reading workspace
    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
    EXEC_KERNEL_CMD(nll_loss, bd, in, tgt32, wc, out, wsF, wsI, tNpu);
    aclrtSynchronizeStream(aclStream);

    if (rm == 1 || rm == 2) {
        at::Tensor sC = wsF.to(at::kCPU);
        at::Tensor cC = wsI.to(at::kCPU);
        float tot = 0.0f; int64_t tc = 0;
        auto sa = sC.accessor<float, 1>();
        auto ca = cC.accessor<int64_t, 1>();
        for (int64_t i = 0; i < nU; ++i) { tot += sa[i]; tc += ca[i]; }
        if (rm == 1 && tc > 0) tot /= static_cast<float>(tc);
        out = at::scalar_tensor(static_cast<double>(tot),
            at::TensorOptions().dtype(in.scalar_type()).device(at::kPrivateUse1));
    }

    return out;
}

}  // namespace ascend_kernel
